import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import ts from 'typescript';
const root=path.dirname(fileURLToPath(import.meta.url));
const files=['packages/coding-agent/src/core/tools/bash.ts','packages/coding-agent/src/core/codemode-constants.ts','packages/coding-agent/src/core/files/session-files.ts','packages/coding-agent/src/core/files/file-parameters.ts'];
const result={};
for(const file of files){const source=fs.readFileSync(file,'utf8');const ast=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true);const counts={arrow:0,functionExpression:0,newPromise:0,newAbortController:0,regex:0,call:0};function visit(n){if(ts.isArrowFunction(n))counts.arrow++;if(ts.isFunctionExpression(n))counts.functionExpression++;if(ts.isRegularExpressionLiteral(n))counts.regex++;if(ts.isCallExpression(n))counts.call++;if(ts.isNewExpression(n)&&n.expression.getText(ast)==='Promise')counts.newPromise++;if(ts.isNewExpression(n)&&n.expression.getText(ast)==='AbortController')counts.newAbortController++;ts.forEachChild(n,visit);}visit(ast);result[file]={source,counts};}
fs.writeFileSync(path.join(root,process.argv[2]+'.json'),JSON.stringify(result,null,2));
console.log(JSON.stringify(Object.fromEntries(Object.entries(result).map(([k,v])=>[k,v.counts]))));

