import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawn} from 'node:child_process';
import assert from 'node:assert/strict';
const root=path.dirname(fileURLToPath(import.meta.url)),mFile=path.join(root,'resources.json');
const results=[];
async function run(label,command,expected){
 const child=spawn('D:/Git/bin/bash.exe',['-c',command],{cwd:root,env:process.env,windowsHide:true,stdio:['ignore','pipe','pipe']});
 const row={label,pid:child.pid,started:new Date().toISOString(),settled:false};
 let m=JSON.parse(fs.readFileSync(mFile,'utf8'));m.processes.push(row);fs.writeFileSync(mFile,JSON.stringify(m,null,2));
 let stdout='',stderr='';child.stdout.on('data',b=>stdout+=b.toString('utf8'));child.stderr.on('data',b=>stderr+=b.toString('utf8'));
 const {code,signal}=await new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(code,signal)=>resolve({code,signal}));});
 Object.assign(row,{code,signal,settled:true,finished:new Date().toISOString()});
 m=JSON.parse(fs.readFileSync(mFile,'utf8'));const item=m.processes.find(p=>p.pid===row.pid&&p.started===row.started);Object.assign(item,row);fs.writeFileSync(mFile,JSON.stringify(m,null,2));
 results.push({...row,command,stdout,stderr});assert.equal(code,expected,label);
}
const fail='python -c "raise RuntimeError(\'SYNTHETIC_PIPELINE_FAILURE\')"';
await run('masked-failure',fail+' 2>&1 | head -8',0);
await run('preserved-failure',fail+' > producer.log 2>&1; producer_status=$?; head -8 producer.log; exit "$producer_status"',1);
await run('preserved-success','python -c "print(\'PRODUCER_OK\')" > success.log 2>&1; producer_status=$?; head -8 success.log; exit "$producer_status"',0);
await run('empty-glob-guard','python -c "import glob; files=glob.glob(\'missing-input-*.aseprite\'); assert files, \'No expected inputs\'"',1);
await run('native-path','python -c "import os,tempfile,json; print(json.dumps(dict(cwd=os.getcwd(),temp=tempfile.gettempdir())))"',0);
for(const r of results)console.log(JSON.stringify(r));
const actual=JSON.parse(results.at(-1).stdout);assert.equal(path.resolve(actual.cwd),root);assert.equal(path.resolve(actual.temp),root);
fs.writeFileSync(path.join(root,'controls.json'),JSON.stringify(results,null,2));

