import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import ts from 'typescript';
import {createAgentSession} from '../../packages/coding-agent/src/core/sdk.ts';
import {DefaultResourceLoader} from '../../packages/coding-agent/src/core/resource-loader.ts';
import {SettingsManager} from '../../packages/coding-agent/src/core/settings-manager.ts';
import {SessionManager} from '../../packages/coding-agent/src/core/session-manager.ts';
import {ALPHA_MODEL,alphaModelRuntime} from '../../tests/helpers/alpha-session.ts';
const root=path.dirname(fileURLToPath(import.meta.url));
const baseline=JSON.parse(fs.readFileSync(path.join(root,'baseline.json'),'utf8')),candidate=JSON.parse(fs.readFileSync(path.join(root,'candidate.json'),'utf8'));
const counters={};
function shape(text){const ast=ts.createSourceFile('source.ts',text,ts.ScriptTarget.Latest,true);function visit(node){if(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node))return undefined;const children=[];let hadChildren=false;ts.forEachChild(node,n=>{hadChildren=true;const v=visit(n);if(v!==undefined)children.push(v);});return [node.kind,hadChildren?children:node.getText(ast)];}return visit(ast);}
for(const file of Object.keys(baseline)){assert.deepEqual(candidate[file].counts,baseline[file].counts,file);assert.deepEqual(shape(candidate[file].source),shape(baseline[file].source),'non-string AST changed: '+file);counters[file]=candidate[file].counts;}
const settings=SettingsManager.inMemory({compaction:{enabled:false},retry:{enabled:false}});
const loader=new DefaultResourceLoader({cwd:root,agentDir:path.join(root,'agent'),settingsManager:settings,noExtensions:true,noContextFiles:true,noSkills:true,noPromptTemplates:true,noThemes:true});
await loader.reload();
const {session}=await createAgentSession({cwd:root,agentDir:path.join(root,'agent'),model:ALPHA_MODEL,modelRuntime:alphaModelRuntime(),settingsManager:settings,sessionManager:SessionManager.inMemory(root),resourceLoader:loader});
const prompt=session.systemPrompt,tools=session.agent.state.modelTools??session.agent.state.tools;
assert.ok(prompt.includes('System32/convert.exe is not ImageMagick'));
assert.ok(prompt.includes('cygpath -w'));
assert.ok(prompt.includes('never invent a snapshot or substitute result.ref'));
const cm=tools.find(t=>t.name==='codemode');assert.ok(cm);assert.ok(cm.description.includes('not a file snapshot ID'));assert.ok(cm.description.includes("producer's exit code"));
const hashes=new Set();for(let i=0;i<100;i++)hashes.add(createHash('sha256').update(session._rebuildSystemPrompt(session.getActiveToolNames())).update(cm.description).digest('hex'));assert.equal(hashes.size,1);
const result={nonStringAstUnchanged:true,counters,promptChars:prompt.length,codemodeDescriptionChars:cm.description.length,rebuilds:100,uniqueHashes:hashes.size,hash:[...hashes][0],tools:tools.map(t=>t.name),verified:'actual AgentSession nested Bash/native write guidance and Codemode description; no provider call'};
session.dispose();await session.waitForSessionLeaseRelease();
fs.writeFileSync(path.join(root,'acceptance.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));

